'use client';
import { useCallback, useEffect, useId, useMemo, useRef, useState, type ButtonHTMLAttributes, type CSSProperties, type ReactNode } from 'react';
import { spring as SPRING, springToLinear, useStudioMotion } from '../../../motion';
import { StudioCanvas, defaultQualityProfiles, detectCapabilities, formatCount, useCanvasDiagnostics, useFrameTiming, type QualityLevel } from '../../../three';
import { Field, type FieldHandle } from './Field';
import { FORMS, buildForms } from './shapes';
import styles from './styles.module.css';

type QualityChoice = QualityLevel | 'auto';

/** No-WebGL still: the sphere form drawn as SVG dots (orthographic, depth as size + tone). */
function SphereStill() {
  const dots = useMemo(() => {
    const f = buildForms(700);
    const out: { x: number; y: number; r: number; o: number }[] = [];
    for (let i = 0; i < 700; i++) {
      const x = f.sphere[i * 3], y = f.sphere[i * 3 + 1], z = f.sphere[i * 3 + 2];
      out.push({ x: x * 100, y: -y * 100, r: 1.1 + (z + 1.7) * 0.55, o: 0.25 + ((z + 1.7) / 3.4) * 0.75 });
    }
    return out.sort((a, b) => a.r - b.r);
  }, []);
  return (
    <svg viewBox="-190 -190 380 380" className={`h-[min(70%,22rem)] w-auto ${styles.still}`} aria-hidden="true">
      {dots.map((d, i) => <circle key={i} cx={d.x} cy={d.y} r={d.r} fill={i % 7 === 0 ? '#ff6a33' : '#f3e7d3'} opacity={d.o} />)}
    </svg>
  );
}

function Readout({ label, value, note }: { label: string; value: string; note?: string }) {
  return (
    <div className="flex items-baseline justify-between gap-3 border-b border-line py-1.5">
      <dt className="text-[12.5px] text-muted">{label}{note ? <span className="ml-1.5 font-mono text-[10.5px] uppercase tracking-[0.06em]">{note}</span> : null}</dt>
      <dd className="m-0 font-mono text-[12.5px] tabular-nums">{value}</dd>
    </div>
  );
}

/* Keycaps lit from above — the field is the light source, the controls sit under it (press-depth-button, adapted). */
type KeyTone = 'glass' | 'signal' | 'paper';
function Key({ tone = 'glass', size = 'm', className, children, ...rest }: ButtonHTMLAttributes<HTMLButtonElement> & { tone?: KeyTone; size?: 's' | 'm' }) {
  return (
    <button type="button" className={`${styles.key} ${className ?? ''}`} data-tone={tone} data-size={size} {...rest}>
      <span className={styles.keyShadow} aria-hidden="true" />
      <span className={styles.keySide} aria-hidden="true" />
      <span className={styles.keyFace}>{children}</span>
    </button>
  );
}
function KeyRadio({ name, checked, onChange, children }: { name: string; checked: boolean; onChange: () => void; children: ReactNode }) {
  return (
    <label className={styles.key} data-tone="glass" data-size="m" data-latch="">
      <input type="radio" className="mk-sr-only" name={name} checked={checked} onChange={onChange} />
      <span className={styles.keyShadow} aria-hidden="true" />
      <span className={styles.keySide} aria-hidden="true" />
      <span className={styles.keyFace}>{children}</span>
    </label>
  );
}

export default function ParticleExperience() {
  const uid = useId();
  const { reduced } = useStudioMotion();
  const [form, setForm] = useState(0);
  const [autoCycle, setAutoCycle] = useState(true);
  const [playing, setPlaying] = useState(true);
  const [intensity, setIntensity] = useState(0.55);
  const [flow, setFlow] = useState(0.5);
  const [count, setCount] = useState(24000);
  const [quality, setQuality] = useState<QualityChoice>('auto');
  const [level, setLevel] = useState<QualityLevel | null>(null);
  const [effective, setEffective] = useState<number | null>(null);
  const [webgl, setWebgl] = useState<boolean | null>(null);
  const field = useRef<FieldHandle>(null);
  const stage = useRef<HTMLDivElement>(null);
  useEffect(() => { setWebgl(detectCapabilities().webgl); }, []);
  const animate = playing && !reduced;
  const diag = useCanvasDiagnostics(500);
  const timing = useFrameTiming(animate && webgl === true);
  const onAdvance = useCallback((next: number) => setForm(next), []);
  const density = level ? defaultQualityProfiles[level].density : null;
  const live = webgl === true && level !== null;
  const release = useMemo(() => springToLinear(SPRING.pop), []);

  // A soft ember light follows the pointer across the stage: CSS variables written directly, no React re-render.
  useEffect(() => {
    const el = stage.current;
    if (!el) return;
    const move = (e: PointerEvent) => {
      const r = el.getBoundingClientRect();
      el.style.setProperty('--px', `${(((e.clientX - r.left) / r.width) * 100).toFixed(1)}%`);
      el.style.setProperty('--py', `${(((e.clientY - r.top) / r.height) * 100).toFixed(1)}%`);
      el.dataset.pointer = 'in';
    };
    const leave = () => { delete el.dataset.pointer; };
    el.addEventListener('pointermove', move, { passive: true });
    el.addEventListener('pointerleave', leave);
    return () => { el.removeEventListener('pointermove', move); el.removeEventListener('pointerleave', leave); };
  }, []);

  const rootStyle = { '--release-ease': release.easing, '--release-dur': `${release.duration}ms` } as CSSProperties;
  const stageStyle = { '--glow': (0.35 + intensity * 0.65).toFixed(2) } as CSSProperties;
  const status = animate ? 'Live' : reduced ? 'Still · reduced motion' : 'Paused';

  return (
    <div data-stage="ink" className={`${styles.root} bg-bg pb-20 text-ink`} style={rootStyle} data-reduced={reduced || undefined}>
      <section aria-label="Particle field" className={styles.hero}>
        <div ref={stage} className={styles.stage} style={stageStyle} data-live={animate || undefined}>
          <div className={styles.nebula} aria-hidden="true" />
          <div className={styles.pointerLight} aria-hidden="true" />
          <StudioCanvas
            key={quality}
            label={`Particle field forming a ${FORMS[form].name.toLowerCase()}`}
            description={`About ${effective ? formatCount(effective) : 'several thousand'} glowing points arranged as a ${FORMS[form].name.toLowerCase()} on a black field; most are warm white, about one in seven is orange. ${animate ? 'They drift slowly, turn towards the pointer and re-form into the next shape every few seconds.' : 'The field is still.'}`}
            quality={quality}
            onQualityChange={setLevel}
            frameloop={animate ? 'always' : 'demand'}
            flat
            camera={{ fov: 36, near: 0.1, far: 50, position: [0, 0.15, 6.6] }}
            style={{ position: 'absolute', inset: 0 }}
            fallback={
              <div className="grid h-full w-full place-items-center gap-2 p-4 text-center">
                <SphereStill />
                <p className="m-0 max-w-[36ch] text-[13.5px] text-ink">A still drawing of the sphere form. The live field needs WebGL.</p>
              </div>
            }
          >
            <Field ref={field} count={count} form={form} autoCycle={autoCycle && !reduced} animate={animate} intensity={intensity} flow={flow} onAdvance={onAdvance} onCount={setEffective} />
          </StudioCanvas>
          <div className={styles.vignette} aria-hidden="true" />

          <div className={styles.heroTop}>
            <div>
              <p className="mk-label m-0 text-muted">Field study № 3 · Obscura Lab (fictional)</p>
              <h2 className={styles.title}>Drift<span className="text-signal">.</span></h2>
            </div>
            <div className={styles.statusCluster}>
              <p className={styles.chip} aria-hidden="true"><span className={styles.dot} data-on={animate || undefined} />{status}</p>
              <Key size="s" onClick={() => setPlaying((p) => !p)} disabled={reduced}>{playing && !reduced ? 'Pause' : 'Play'}</Key>
            </div>
          </div>

          <p className={styles.formTag} aria-hidden="true"><span className="mk-label">{String(form + 1).padStart(2, '0')} / 03</span><span className={styles.formName}>{FORMS[form].name}</span></p>

          <div className={styles.dock}>
            <fieldset className={styles.dockForms}>
              <legend className="mk-sr-only">Form</legend>
              {FORMS.map((f, i) => (
                <KeyRadio key={f.id} name={`${uid}form`} checked={form === i} onChange={() => setForm(i)}>{f.name}</KeyRadio>
              ))}
            </fieldset>
            <span className={styles.dockRule} aria-hidden="true" />
            <Key tone="signal" onClick={() => field.current?.pulse()} disabled={!animate || !live}>Pulse</Key>
          </div>
        </div>
        <p className="mx-auto mt-3 max-w-[1360px] px-4 text-[13px] leading-snug text-muted @3xl:px-8">
          {reduced
            ? 'Reduced motion is on, so the field is a still frame. Every control still redraws it.'
            : 'Move a pointer or drag a finger sideways across the field to push it; the field turns to follow you. Pulse sends a ring through it from the keyboard.'}
        </p>
      </section>

      <div className="mx-auto mt-10 grid max-w-[1360px] gap-8 px-4 @3xl:px-8 @4xl:grid-cols-[minmax(0,1fr)_minmax(0,24rem)] @4xl:gap-10">
        <div className="min-w-0">
          <p className="m-0 max-w-[48ch] font-serif text-[clamp(1.4rem,3.2cqi,2rem)] leading-[1.2]">
            Thousands of points, each remembering its place on three forms. The GPU moves all of them every frame; your pointer, a finger, or the Pulse button pushes them around.
          </p>
          <section className="mt-10 grid gap-6 @2xl:grid-cols-3" aria-label="How it works">
            {[
              ['One draw call', 'Every point is a vertex of a single THREE.Points object. Positions are never written from JavaScript: the vertex shader blends each particle between its three stored forms and adds the flow, the pointer push and the pulse ring.'],
              ['Glow and depth in the shader', 'Each point is a white-hot core in a soft halo, and additive blending turns overlaps into bloom. Points behind the focus plane dim and cool; points away from it spread into wider, fainter discs — depth of field without a postprocessing pass.'],
              ['Still when asked', 'With reduced motion, or when paused, the loop switches to render-on-demand: one frame per change. Forms cut instead of morphing, the field stops turning to the pointer, and the flow slider picks the frozen phase.'],
            ].map(([t, b]) => (
              <div key={t} className="border-t border-line-strong pt-3">
                <h3 className="m-0 font-display text-[1.05rem] font-semibold">{t}</h3>
                <p className="m-0 mt-2 text-[13.5px] leading-relaxed text-muted">{b}</p>
              </div>
            ))}
          </section>
        </div>

        <form className={styles.panel} aria-label="Field controls" onSubmit={(e) => e.preventDefault()}>
          <section aria-labelledby={`${uid}formh`}>
            <h3 id={`${uid}formh`} className="mk-label m-0 mb-1.5 text-muted">Form · {FORMS[form].name}</h3>
            {/* All three notes share one grid cell, so the panel never changes height when the form cycles. */}
            <p className={styles.notes}>
              {FORMS.map((f, i) => <span key={f.id} data-shown={form === i || undefined} aria-hidden={form !== i || undefined}>{f.note}</span>)}
            </p>
            <label className="mt-2 flex min-h-9 items-center gap-2 text-[13px]">
              <input type="checkbox" className={styles.check} checked={autoCycle && !reduced} disabled={reduced} onChange={(e) => setAutoCycle(e.target.checked)} />
              Cycle forms every few seconds{reduced ? ' (off with reduced motion)' : ''}
            </label>
          </section>

          <div className="grid gap-3 border-t border-line pt-4">
            <label className="grid gap-1 text-[13px]">
              <span className="flex justify-between"><span>Intensity</span><span className="font-mono text-[12px] text-muted">{Math.round(intensity * 100)}%</span></span>
              <input type="range" className={styles.range} min={0} max={100} value={Math.round(intensity * 100)} onChange={(e) => setIntensity(Number(e.target.value) / 100)} />
            </label>
            <label className="grid gap-1 text-[13px]">
              <span className="flex justify-between"><span>Flow speed</span><span className="font-mono text-[12px] text-muted">{flow.toFixed(2)}×</span></span>
              <input type="range" className={styles.range} min={0} max={200} value={Math.round(flow * 100)} onChange={(e) => setFlow(Number(e.target.value) / 100)} aria-valuetext={`${flow.toFixed(2)} times`} />
            </label>
            <label className="grid gap-1 text-[13px]">
              <span className="flex justify-between"><span>Particles</span><span className="font-mono text-[12px] text-muted">{formatCount(count)} requested</span></span>
              <input type="range" className={styles.range} min={4000} max={60000} step={2000} value={count} onChange={(e) => setCount(Number(e.target.value))} aria-valuetext={`${count} requested`} />
              <span className={`${styles.reserve} text-[12.5px] leading-snug text-muted`} aria-live="polite">
                {effective && density != null ? `Rendering ${formatCount(effective)} — ${formatCount(count)} × ${density} density for the ${level} profile.` : 'Scaled by the quality profile once 3D starts.'}
              </span>
            </label>
            <label className="grid gap-1 text-[13px]">
              <span>Quality</span>
              <select className={styles.select} value={quality} onChange={(e) => setQuality(e.target.value as QualityChoice)}>
                <option value="auto">Auto{quality === 'auto' && level ? ` (${level})` : ''}</option>
                <option value="low">Low</option>
                <option value="medium">Medium</option>
                <option value="high">High</option>
              </select>
              <span className="text-[12.5px] leading-snug text-muted">Changing it rebuilds the canvas with that profile’s pixel ratio, antialiasing and density.</span>
            </label>
          </div>

          <section aria-labelledby={`${uid}diag`} className="border-t border-line pt-4">
            <h3 id={`${uid}diag`} className="mk-label m-0 mb-1 text-muted">Readout · renderer.info, last frame</h3>
            <dl className="m-0" data-particle-diagnostics="">
              <Readout label="Draw calls" value={live ? formatCount(diag?.renderer.calls) : '—'} />
              <Readout label="Points drawn" value={live ? formatCount(diag?.renderer.points) : '—'} />
              <Readout label="Shader programs" value={live ? formatCount(diag?.renderer.programs) : '—'} />
              <Readout label="Geometries in memory" value={live ? formatCount(diag?.renderer.geometries) : '—'} />
              <Readout label="Pixel ratio" value={live && diag ? diag.dpr.toFixed(2) : '—'} />
              <Readout label="Frames drawn" value={live ? formatCount(diag?.frames) : '—'} />
              <Readout label="Frame interval" note="measured on this device" value={animate && timing.medianMs != null ? `${timing.medianMs.toFixed(1)} ms median · ${timing.p95Ms?.toFixed(1)} p95` : '—'} />
            </dl>
            <p className="m-0 mt-2 text-[12px] leading-snug text-muted">The interval is the browser’s own frame cadence on this machine, sampled over 60 frames while the field runs. It is not a benchmark and says nothing about other hardware.</p>
          </section>
        </form>
      </div>
    </div>
  );
}

'use client';
import { useFrame, useThree } from '@react-three/fiber';
import { forwardRef, useEffect, useImperativeHandle, useMemo, useRef } from 'react';
import { AdditiveBlending, BufferAttribute, BufferGeometry, Color, Matrix4, Plane, Raycaster, ShaderMaterial, Sphere, Vector2, Vector3, type Points } from 'three';
import { useQuality } from '../../../three';
import { FORMS, buildForms } from './shapes';
import { fragmentShader, vertexShader } from './shaders';

export interface FieldHandle { pulse(): void }
export interface FieldProps {
  /** Requested particle count before the quality profile's density is applied. */
  count: number;
  /** Target form index (0 sphere, 1 torus, 2 glyph). */
  form: number;
  autoCycle: boolean;
  /** Animate (flow, morphs, pointer, pulse). False = a still frame that still follows every control. */
  animate: boolean;
  intensity: number;
  /** Flow speed; in a still frame it chooses the frozen phase of the flow instead. */
  flow: number;
  /** The field finished a hold and wants the next form (auto-cycle). */
  onAdvance: (next: number) => void;
  /** Effective particle count after quality scaling. */
  onCount?: (n: number) => void;
}

const MORPH_SECONDS = 2.4;
const HOLD_SECONDS = 5;
const PULSE_SECONDS = 1.5;

export const Field = forwardRef<FieldHandle, FieldProps>(function Field({ count, form, autoCycle, animate, intensity, flow, onAdvance, onCount }, ref) {
  const quality = useQuality();
  const gl = useThree((s) => s.gl);
  const invalidate = useThree((s) => s.invalidate);
  const effective = Math.max(600, Math.round((count * quality.density) / 100) * 100);
  const points = useRef<Points>(null);

  const geometry = useMemo(() => {
    const f = buildForms(effective);
    const g = new BufferGeometry();
    g.setAttribute('position', new BufferAttribute(f.sphere, 3));
    g.setAttribute('aSphere', new BufferAttribute(f.sphere, 3));
    g.setAttribute('aTorus', new BufferAttribute(f.torus, 3));
    g.setAttribute('aGlyph', new BufferAttribute(f.glyph, 3));
    g.setAttribute('aSeed', new BufferAttribute(f.seed, 4));
    g.boundingSphere = new Sphere(new Vector3(), 3.5);
    return g;
  }, [effective]);
  useEffect(() => () => geometry.dispose(), [geometry]);
  useEffect(() => { onCount?.(effective); invalidate(); }, [effective, onCount, invalidate]);

  const material = useMemo(() => new ShaderMaterial({
    vertexShader, fragmentShader, transparent: true, depthWrite: false, blending: AdditiveBlending,
    uniforms: {
      uTime: { value: 0 }, uFrom: { value: form }, uTo: { value: form }, uProgress: { value: 1 }, uIntensity: { value: intensity },
      uSize: { value: 2 }, uPixelRatio: { value: 1 }, uPointer: { value: new Vector3(0, 0, 99) }, uPointerStrength: { value: 0 },
      uPulse: { value: new Vector2(0, 0) }, uColorA: { value: new Color('#f6e9d4') }, uColorB: { value: new Color('#ff6a33') }, uAccentShare: { value: 0.14 },
      uColorFar: { value: new Color('#6f7f9e') }, uFocus: { value: 6.6 },
    },
  }), []); // eslint-disable-line react-hooks/exhaustive-deps
  useEffect(() => () => material.dispose(), [material]);

  // Mutable simulation state: never React state (no per-frame re-renders).
  const sim = useRef({ from: form, to: form, progress: 1, hold: 0, time: 0, pulse: -1, pointerAt: -1e9, inside: false, strength: 0, spin: 0, tiltX: 0, tiltY: 0 });
  const live = useRef({ animate, autoCycle, onAdvance, flow });
  live.current = { animate, autoCycle, onAdvance, flow };

  useImperativeHandle(ref, () => ({ pulse() { if (live.current.animate) { sim.current.pulse = 0; invalidate(); } } }), [invalidate]);

  // A new target form: morph from whichever form the field is closest to (a cut when animation is off).
  useEffect(() => {
    const s = sim.current;
    if (form === s.to && s.progress >= 1) return;
    if (!animate) { s.from = s.to = form; s.progress = 1; }
    else if (form !== s.to) { s.from = s.progress < 0.5 ? s.from : s.to; s.to = form; s.progress = 0; }
    s.hold = 0;
    invalidate();
  }, [form, animate, invalidate]);
  useEffect(() => {
    const s = sim.current;
    if (!animate) { s.from = s.to; s.progress = 1; s.pulse = -1; s.strength = 0; }
    invalidate();
  }, [animate, invalidate]);
  useEffect(() => { material.uniforms.uIntensity.value = intensity; invalidate(); }, [intensity, material, invalidate]);
  useEffect(() => { if (!animate) { sim.current.time = flow * 6.5; } invalidate(); }, [flow, animate, invalidate]);

  // Pointer / touch presence on the canvas element (R3F keeps the last pointer position after leave).
  useEffect(() => {
    const el = gl.domElement;
    const prevTouch = el.style.touchAction;
    // Sideways drags push the field; vertical swipes still scroll the page (the hero is tall: never trap scrolling).
    el.style.touchAction = 'pan-y';
    const move = () => { sim.current.pointerAt = performance.now(); sim.current.inside = true; invalidate(); };
    const leave = () => { sim.current.inside = false; invalidate(); };
    el.addEventListener('pointermove', move);
    el.addEventListener('pointerdown', move);
    el.addEventListener('pointerleave', leave);
    el.addEventListener('pointercancel', leave);
    return () => {
      el.style.touchAction = prevTouch;
      el.removeEventListener('pointermove', move); el.removeEventListener('pointerdown', move);
      el.removeEventListener('pointerleave', leave); el.removeEventListener('pointercancel', leave);
    };
  }, [gl, invalidate]);

  const tmp = useMemo(() => ({ ray: new Raycaster(), plane: new Plane(), hit: new Vector3(), n: new Vector3(), inv: new Matrix4() }), []);

  useFrame((state, rawDt) => {
    const s = sim.current, u = material.uniforms;
    const dt = Math.min(rawDt, 1 / 20);
    const { animate: on, autoCycle: cycle, flow: speed } = live.current;
    let busy = false;
    if (on) {
      s.time += dt * (0.25 + speed * 1.15);
      s.spin += dt * 0.06;
      if (s.progress < 1) { s.progress = Math.min(1, s.progress + dt / MORPH_SECONDS); busy = true; if (s.progress >= 1) s.from = s.to; }
      else if (cycle) { s.hold += dt; if (s.hold > HOLD_SECONDS) { s.hold = 0; live.current.onAdvance((s.to + 1) % FORMS.length); } }
      if (s.pulse >= 0) { s.pulse += dt; if (s.pulse > PULSE_SECONDS) s.pulse = -1; busy = true; }
      const want = s.inside && performance.now() - s.pointerAt < 1400 ? 1 : 0;
      s.strength += (want - s.strength) * Math.min(1, dt * (want ? 6 : 2.5));
      if (Math.abs(want - s.strength) > 0.002) busy = true;
    }
    if (on) {
      // Parallax: the whole field turns a little towards the pointer and drifts back when it leaves (smoothed).
      const k = 1 - Math.exp(-dt * 3.2);
      const px = s.inside ? state.pointer.x : 0, py = s.inside ? state.pointer.y : 0;
      s.tiltX += (-py * 0.2 - s.tiltX) * k;
      s.tiltY += (px * 0.32 - s.tiltY) * k;
      if (Math.abs(-py * 0.2 - s.tiltX) + Math.abs(px * 0.32 - s.tiltY) > 1e-3) busy = true;
    }
    if (points.current) { points.current.rotation.x = s.tiltX; points.current.rotation.y = s.spin + s.tiltY; }
    u.uFocus.value = state.camera.position.length();
    // pointer → a point on the plane through the field's centre, facing the camera, in the field's local space
    if (s.strength > 0.001 && points.current) {
      tmp.ray.setFromCamera(state.pointer, state.camera);
      state.camera.getWorldDirection(tmp.n);
      tmp.plane.setFromNormalAndCoplanarPoint(tmp.n, points.current.getWorldPosition(tmp.hit));
      if (tmp.ray.ray.intersectPlane(tmp.plane, tmp.hit)) {
        points.current.updateMatrixWorld();
        (u.uPointer.value as Vector3).copy(tmp.hit).applyMatrix4(tmp.inv.copy(points.current.matrixWorld).invert());
      }
    }
    u.uTime.value = s.time;
    u.uFrom.value = s.from; u.uTo.value = s.to; u.uProgress.value = s.progress;
    u.uPointerStrength.value = s.strength;
    (u.uPulse.value as Vector2).set(Math.max(0, s.pulse), s.pulse >= 0 ? 1 - s.pulse / PULSE_SECONDS : 0);
    u.uPixelRatio.value = gl.getPixelRatio();
    u.uSize.value = 2.1 * Math.sqrt(Math.sqrt(24000 / effective));
    // In a demand loop (paused / reduced) keep drawing only while something is still settling.
    if (busy && state.frameloop === 'demand') invalidate();
  });

  return <points ref={points} geometry={geometry} material={material} frustumCulled={false} />;
});

/**
 * The whole field moves in the vertex shader: the CPU only updates a handful of uniforms per frame.
 * Each particle carries its point on all three forms (aSphere, aTorus, aGlyph) and a random seed vector.
 *
 * Light and depth without a postprocessing pass:
 *  - every point is a glowing sprite: a white-hot core inside a soft halo (additive blending does the bloom);
 *  - depth falls off like a lens and an atmosphere: points far behind the focus plane dim and cool, points away
 *    from the focus plane in either direction spread into larger, fainter discs (a cheap depth of field).
 */
export const vertexShader = /* glsl */ `
attribute vec3 aSphere;
attribute vec3 aTorus;
attribute vec3 aGlyph;
attribute vec4 aSeed;

uniform float uTime;
uniform float uFrom;
uniform float uTo;
uniform float uProgress;
uniform float uIntensity;
uniform float uSize;
uniform float uPixelRatio;
uniform vec3 uPointer;
uniform float uPointerStrength;
uniform vec2 uPulse;
uniform float uFocus;

varying float vPick;
varying float vGlow;
varying float vAlpha;
varying float vDepth;

vec3 formAt(float i) { return i < 0.5 ? aSphere : (i < 1.5 ? aTorus : aGlyph); }

// Cheap divergence-light swirl: sums of offset sines, phase-shifted per particle.
vec3 flow(vec3 p, float t) {
  float ph = aSeed.w * 6.2831;
  return vec3(
    sin(p.y * 1.7 + t * 0.9 + ph) + sin(p.z * 2.3 - t * 0.6),
    sin(p.z * 1.9 + t * 0.7 + ph * 0.5) + sin(p.x * 2.1 + t * 0.5),
    sin(p.x * 1.5 - t * 0.8 + ph * 0.75) + sin(p.y * 2.6 + t * 0.4)
  ) * 0.5;
}

void main() {
  float stagger = 0.65;
  float p = clamp(uProgress * (1.0 + stagger) - aSeed.x * stagger, 0.0, 1.0);
  p = p * p * (3.0 - 2.0 * p);
  vec3 pos = mix(formAt(uFrom), formAt(uTo), p);
  float flight = sin(p * 3.14159265);
  // mid-flight the particles bloom outwards, then settle onto the new form
  pos += normalize(pos + vec3(1e-4)) * flight * (0.35 + 0.5 * aSeed.y);
  pos += flow(pos * 0.9, uTime) * (0.03 + 0.2 * uIntensity) * (0.7 + flight);

  vec3 d = pos - uPointer;
  float push = uPointerStrength * exp(-dot(d, d) * 2.4);
  pos += normalize(d + vec3(1e-4)) * push * 0.85;

  float rr = length(pos) - uPulse.x * 3.4;          // squared explicitly: pow() of a negative base is undefined
  float ring = exp(-rr * rr * 5.0) * uPulse.y;
  pos += normalize(pos + vec3(1e-4)) * ring * 0.55;

  vec4 mv = modelViewMatrix * vec4(pos, 1.0);
  gl_Position = projectionMatrix * mv;
  float dist = -mv.z;
  float depth = clamp((dist - uFocus + 1.7) / 3.4, 0.0, 1.0);      // 0 = nearest, 1 = farthest
  float defocus = min(1.5, abs(dist - uFocus) / 1.45);
  float size = uSize * (0.55 + aSeed.y * 0.9) * (1.0 + push * 1.4 + ring * 1.2);
  size *= 1.0 + defocus * defocus * 0.85;                          // out of focus: wider…
  gl_PointSize = size * uPixelRatio * (6.0 / max(0.5, dist)) * 2.3; // ×2.3 leaves room for the halo
  vPick = aSeed.z;
  vGlow = clamp(0.5 + 0.55 * uIntensity + push * 0.9 + ring * 1.3 + flight * 0.45, 0.0, 2.4);
  vAlpha = (1.0 - depth * 0.6) / (1.0 + defocus * defocus * 1.25); // …and fainter; far points fade
  vDepth = depth;
}
`;

export const fragmentShader = /* glsl */ `
uniform vec3 uColorA;
uniform vec3 uColorB;
uniform vec3 uColorFar;
uniform float uAccentShare;
varying float vPick;
varying float vGlow;
varying float vAlpha;
varying float vDepth;

void main() {
  vec2 c = (gl_PointCoord - 0.5) * 2.0;
  float r2 = dot(c, c);
  if (r2 > 1.0) discard;
  float core = exp(-r2 * 24.0);
  float halo = exp(-r2 * 4.6) * 0.3;
  vec3 base = vPick > 1.0 - uAccentShare ? uColorB : uColorA;
  base = mix(base, uColorFar, vDepth * 0.55);                      // atmospheric: far points cool and grey
  vec3 col = base * vGlow + vec3(1.0, 0.93, 0.82) * core * 0.5 * vGlow;
  gl_FragColor = vec4(col, (core + halo) * vAlpha);
  #include <colorspace_fragment>
}
`;

/**
 * Target forms for the particle field. Deterministic (seeded): the same count always yields the same points.
 * Every particle owns one point on each form, so a morph is a per-particle interpolation done in the vertex shader.
 */
export const FORMS = [
  { id: 'sphere', name: 'Sphere', note: 'A Fibonacci lattice on a sphere: evenly spaced, no poles.' },
  { id: 'torus', name: 'Torus', note: 'Uniform samples on a tilted ring.' },
  { id: 'glyph', name: 'Glyph', note: 'An abstract mark: a ring crossed by a stroke, a tick and a dot.' },
] as const;
export type FormId = (typeof FORMS)[number]['id'];
export const formIndex = (id: FormId): number => FORMS.findIndex((f) => f.id === id);

function rng(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
const gauss = (r: () => number) => Math.sqrt(-2 * Math.log(Math.max(1e-9, r()))) * Math.cos(2 * Math.PI * r());

type Stroke = { kind: 'line'; a: [number, number]; b: [number, number]; w: number } | { kind: 'arc'; c: [number, number]; r: number; from: number; to: number; w: number } | { kind: 'dot'; c: [number, number]; r: number };
const GLYPH: Stroke[] = [
  { kind: 'arc', c: [-0.1, 0.05], r: 1.2, from: 0.35, to: Math.PI * 2 - 0.15, w: 0.09 },
  { kind: 'line', a: [-1.65, -1.35], b: [1.55, 1.45], w: 0.1 },
  { kind: 'line', a: [-1.45, 1.05], b: [-0.85, 1.05], w: 0.07 },
  { kind: 'dot', c: [1.02, -0.98], r: 0.26 },
];
const strokeLength = (s: Stroke): number => (s.kind === 'line' ? Math.hypot(s.b[0] - s.a[0], s.b[1] - s.a[1]) : s.kind === 'arc' ? s.r * (s.to - s.from) : Math.PI * s.r * 1.6);

export interface FormBuffers { sphere: Float32Array; torus: Float32Array; glyph: Float32Array; seed: Float32Array }

export function buildForms(count: number): FormBuffers {
  const r = rng(0x5eed + count);
  const sphere = new Float32Array(count * 3), torus = new Float32Array(count * 3), glyph = new Float32Array(count * 3), seed = new Float32Array(count * 4);
  const golden = Math.PI * (3 - Math.sqrt(5));
  const tilt = 1.02, ct = Math.cos(tilt), st = Math.sin(tilt);
  const lengths = GLYPH.map(strokeLength), total = lengths.reduce((a, b) => a + b, 0);
  for (let i = 0; i < count; i++) {
    // sphere: Fibonacci lattice, thin shell
    const y = 1 - (i / Math.max(1, count - 1)) * 2, rad = Math.sqrt(1 - y * y), th = golden * i;
    const R = 1.62 + gauss(r) * 0.035;
    sphere.set([Math.cos(th) * rad * R, y * R, Math.sin(th) * rad * R], i * 3);
    // torus: area-uniform (rejection on the minor angle), tilted towards the viewer
    const Rm = 1.32, rm = 0.5;
    let v = 0;
    for (let k = 0; k < 8; k++) { v = r() * Math.PI * 2; if (r() < (Rm + rm * Math.cos(v)) / (Rm + rm)) break; }
    const u = r() * Math.PI * 2, rr = rm + gauss(r) * 0.02;
    const tx = (Rm + rr * Math.cos(v)) * Math.cos(u), tz = (Rm + rr * Math.cos(v)) * Math.sin(u), ty = rr * Math.sin(v);
    torus.set([tx, ty * ct - tz * st, ty * st + tz * ct], i * 3);
    // glyph: strokes sampled by length, with thickness and a little depth
    let pick = r() * total, s = GLYPH[0];
    for (let k = 0; k < GLYPH.length; k++) { if (pick <= lengths[k]) { s = GLYPH[k]; break; } pick -= lengths[k]; }
    let gx = 0, gy = 0;
    if (s.kind === 'line') { const t = r(); gx = s.a[0] + (s.b[0] - s.a[0]) * t + gauss(r) * s.w * 0.5; gy = s.a[1] + (s.b[1] - s.a[1]) * t + gauss(r) * s.w * 0.5; }
    else if (s.kind === 'arc') { const a = s.from + (s.to - s.from) * r(), rr2 = s.r + gauss(r) * s.w * 0.5; gx = s.c[0] + Math.cos(a) * rr2; gy = s.c[1] + Math.sin(a) * rr2; }
    else { const a = r() * Math.PI * 2, d = Math.sqrt(r()) * s.r; gx = s.c[0] + Math.cos(a) * d; gy = s.c[1] + Math.sin(a) * d; }
    glyph.set([gx, gy, gauss(r) * 0.08], i * 3);
    // x: morph stagger, y: size, z: colour pick, w: flow phase
    seed.set([r(), r(), r(), r()], i * 4);
  }
  return { sphere, torus, glyph, seed };
}

/* Drift — the field is the light source. It glows in the dark; everything around it is lit from above by it:
   highlights on top edges, shadows falling straight down. One ember accent. */
.root { min-height: 100%; }

/* ── Hero: the field fills the stage edge to edge ──────────────────────────────────────────────────────── */
.hero { position: relative; }
.stage {
  --px: 50%;
  --py: 45%;
  position: relative;
  overflow: hidden;
  width: 100%;
  height: clamp(32rem, 84svh, 60rem);
  background: #090807;
  isolation: isolate;
}
@container (width < 40rem) { .stage { height: max(32rem, 78svh); } }

/* a slow ember nebula behind the field; its strength follows the Intensity control */
.nebula {
  position: absolute;
  inset: 0;
  z-index: -1;
  background:
    radial-gradient(34% 42% at 50% 47%, rgb(255 106 51 / calc(0.2 * var(--glow, 0.7))) 0%, rgb(255 106 51 / 0) 70%),
    radial-gradient(60% 70% at 50% 46%, rgb(246 233 212 / calc(0.08 * var(--glow, 0.7))) 0%, rgb(246 233 212 / 0) 72%),
    radial-gradient(120% 90% at 50% 40%, #15120f 0%, #090807 64%);
  pointer-events: none;
}
/* a warm light that follows the pointer across the stage */
.pointerLight {
  position: absolute;
  inset: 0;
  z-index: -1;
  background: radial-gradient(26rem 26rem at var(--px) var(--py), rgb(255 138 90 / 0.13) 0%, rgb(255 138 90 / 0) 70%);
  opacity: 0;
  pointer-events: none;
}
.stage[data-pointer] .pointerLight { opacity: 1; }
@media (prefers-reduced-motion: no-preference) {
  .pointerLight { transition: opacity var(--mk-duration-slow, 560ms) var(--mk-ease-standard, ease); }
}
.vignette {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background:
    radial-gradient(130% 100% at 50% 48%, rgb(0 0 0 / 0) 52%, rgb(0 0 0 / 0.55) 100%),
    linear-gradient(180deg, rgb(9 8 7 / 0.55) 0%, rgb(9 8 7 / 0) 22%, rgb(9 8 7 / 0) 74%, rgb(9 8 7 / 0.7) 100%);
}
.still { filter: drop-shadow(0 0 10px rgb(255 120 70 / 0.35)); }

.heroTop {
  position: absolute;
  inset: 0 0 auto;
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
  padding: clamp(16px, 3cqi, 32px) clamp(16px, 3cqi, 32px) 0;
  pointer-events: none;
}
.title {
  margin: 10px 0 0;
  font-family: var(--mk-font-serif, Georgia, serif);
  font-style: italic;
  font-weight: 400;
  font-size: clamp(3.6rem, 13cqi, 9.5rem);
  line-height: 0.82;
  letter-spacing: -0.03em;
  text-shadow: 0 0 40px rgb(255 106 51 / 0.18);
}
.statusCluster { display: flex; align-items: center; gap: 10px; pointer-events: auto; }
.chip {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  margin: 0;
  padding: 6px 11px;
  border: 1px solid var(--mk-line, #f3f0e826);
  border-radius: 999px;
  background: rgb(12 11 10 / 0.6);
  font: 500 11px/1 var(--mk-font-mono, ui-monospace, monospace);
  letter-spacing: 0.08em;
  text-transform: uppercase;
}
.dot { width: 7px; height: 7px; border-radius: 50%; background: var(--mk-ink-muted, #a8a59a); }
.dot[data-on] { background: var(--mk-signal, #ff5a2b); box-shadow: 0 0 10px 2px rgb(255 90 43 / 0.55); }

.formTag {
  position: absolute;
  left: clamp(16px, 3cqi, 32px);
  bottom: clamp(18px, 3cqi, 30px);
  display: grid;
  gap: 6px;
  margin: 0;
  pointer-events: none;
  color: var(--mk-ink-muted, #a8a59a);
}
.formName {
  font-family: var(--mk-font-serif, Georgia, serif);
  font-style: italic;
  font-size: clamp(1.9rem, 5cqi, 3.2rem);
  line-height: 0.95;
  color: var(--mk-ink, #f3f0e8);
}
@container (width < 52rem) { .formTag { bottom: 104px; } }

.dock {
  position: absolute;
  left: 50%;
  bottom: clamp(16px, 3cqi, 28px);
  display: flex;
  align-items: center;
  gap: 12px;
  max-width: calc(100% - 24px);
  padding: 10px 12px 12px;
  border: 1px solid rgb(243 240 232 / 0.12);
  border-radius: 20px;
  background: linear-gradient(180deg, rgb(40 34 30 / 0.62), rgb(16 14 12 / 0.72));
  box-shadow: inset 0 1px 0 rgb(255 236 214 / 0.14), 0 18px 40px -18px rgb(0 0 0 / 0.9);
  backdrop-filter: blur(14px) saturate(1.2);
  transform: translateX(-50%);
}
.dockForms { display: flex; gap: 8px; margin: 0; padding: 0; border: 0; min-width: 0; }
.dockRule { width: 1px; align-self: stretch; margin: 4px 0 8px; background: rgb(243 240 232 / 0.14); }
@container (width < 30rem) {
  .dock { gap: 8px; padding: 8px 8px 10px; }
  .dockForms { gap: 6px; }
}

/* ── Keycaps (press-depth-button, adapted to a dark stage lit from above) ───────────────────────────────── */
.key {
  --d: 4px;
  --face: rgb(255 246 234 / 0.07);
  --side: rgb(0 0 0 / 0.55);
  --text: var(--mk-ink, #f3f0e8);
  --edge: rgb(243 240 232 / 0.16);
  --lip: rgb(255 240 222 / 0.22);
  position: relative;
  isolation: isolate;
  display: grid;
  flex: none;
  min-width: 2.75rem;
  margin: 0;
  padding: 0 0 var(--d);
  border: 0;
  border-radius: 12px;
  background: none;
  color: var(--text);
  font: inherit;
  font-size: 13.5px;
  cursor: pointer;
  user-select: none;
  touch-action: manipulation;
  -webkit-tap-highlight-color: transparent;
}
.key[data-size='s'] { --d: 3px; border-radius: 999px; font-size: 12.5px; }
.key[data-tone='signal'] {
  --face: var(--mk-signal, #ff5a2b);
  --side: color-mix(in oklab, var(--mk-signal, #ff5a2b) 45%, #000);
  --text: var(--mk-on-signal, #11110f);
  --edge: transparent;
  --lip: rgb(255 226 200 / 0.55);
}
.keyShadow {
  position: absolute;
  z-index: -1;
  inset: auto 6% calc(var(--d) * -0.6) 6%;
  height: 60%;
  border-radius: 45%;
  background: rgb(0 0 0 / 0.7);
  filter: blur(6px);
  transform: translateY(3px);
  transition:
    transform var(--release-dur, 600ms) var(--release-ease, ease),
    opacity var(--release-dur, 600ms) var(--release-ease, ease);
}
.keySide {
  position: absolute;
  inset: var(--d) 0 0;
  border-radius: inherit;
  background: var(--side);
  box-shadow: inset 0 0 0 1px var(--edge), 0 1px 1px rgb(0 0 0 / 0.6);
}
.keyFace {
  position: relative;
  display: grid;
  place-items: center;
  min-height: 2.75rem;
  padding: 0 1.05rem;
  border-radius: inherit;
  background: linear-gradient(180deg, color-mix(in oklab, var(--face) 86%, #fff3e4) 0%, var(--face) 60%);
  box-shadow: inset 0 0 0 1px var(--edge), inset 0 1px 0 var(--lip);
  font-weight: 550;
  white-space: nowrap;
  backdrop-filter: blur(6px);
  transform: translateY(0);
  transition: transform var(--release-dur, 600ms) var(--release-ease, ease), box-shadow var(--mk-duration-fast, 160ms) var(--mk-ease-standard, ease);
}
.key[data-size='s'] .keyFace { min-height: 2.125rem; padding: 0 0.95rem; }
@container (width < 30rem) { .key[data-size='m'] .keyFace { padding: 0 0.7rem; } }

@media (hover: hover) {
  .key:hover:not(:disabled):not(:has(input:disabled)) .keyFace { transform: translateY(-2px); box-shadow: inset 0 0 0 1px rgb(255 214 190 / 0.32), inset 0 1px 0 var(--lip), 0 0 18px -4px rgb(255 106 51 / 0.45); }
  .key:hover:not(:disabled):not(:has(input:disabled)) .keyShadow { transform: translateY(7px) scale(1.06); opacity: 0.85; }
}
.key:active:not(:disabled):not(:has(input:disabled)) .keyFace {
  transform: translateY(calc(var(--d) * 0.85));
  transition: transform var(--mk-duration-instant, 90ms) var(--mk-ease-standard, ease);
}
.key:active:not(:disabled):not(:has(input:disabled)) .keyShadow {
  transform: translateY(1px) scale(0.9, 0.45);
  opacity: 0.5;
  transition: transform var(--mk-duration-instant, 90ms) var(--mk-ease-standard, ease), opacity var(--mk-duration-instant, 90ms) var(--mk-ease-standard, ease);
}
/* the chosen form stays pressed in and lit like the field */
.key[data-latch]:has(input:checked) {
  --face: var(--mk-ink, #f3f0e8);
  --side: color-mix(in oklab, var(--mk-ink, #f3f0e8) 40%, #000);
  --text: var(--mk-bg, #0e0e0c);
  --edge: transparent;
  --lip: rgb(255 255 255 / 0.7);
}
.key[data-latch]:has(input:checked) .keyFace { transform: translateY(calc(var(--d) * 0.55)); box-shadow: inset 0 1px 0 var(--lip), 0 0 22px -6px rgb(255 214 170 / 0.6); }
.key[data-latch]:has(input:checked) .keyShadow { transform: translateY(1.5px) scale(0.95, 0.6); opacity: 0.7; }
.key:focus-visible, .key:has(input:focus-visible) { outline: 2px solid var(--mk-focus, #8ab4ff); outline-offset: 3px; }
.key:disabled, .key:has(input:disabled) {
  cursor: not-allowed;
  --face: rgb(255 246 234 / 0.03);
  --side: rgb(0 0 0 / 0.4);
  --text: var(--mk-ink-muted, #a8a59a);
  --edge: rgb(243 240 232 / 0.1);
  --lip: transparent;
}
.key:disabled .keyFace, .key:has(input:disabled) .keyFace { transform: translateY(calc(var(--d) * 0.9)); }
.key:disabled .keyShadow, .key:has(input:disabled) .keyShadow { opacity: 0; }
.root[data-reduced] .keyFace, .root[data-reduced] .keyShadow { transition: none; }
@media (prefers-reduced-motion: reduce) { .keyFace, .keyShadow { transition: none; } }

/* ── Instrument panel under the field ───────────────────────────────────────────────────────────────────── */
.panel {
  display: grid;
  align-content: start;
  gap: 16px;
  min-width: 0;
  padding: 18px;
  border: 1px solid var(--mk-line, #f3f0e826);
  border-radius: var(--mk-radius-m, 10px);
  background: linear-gradient(180deg, #1c1916 0%, var(--mk-surface, #171714) 40%);
  box-shadow: inset 0 1px 0 rgb(255 236 214 / 0.08), 0 22px 44px -26px rgb(0 0 0 / 0.9);
}
/* the three form notes share one cell: the panel keeps the height of the longest one */
.notes { display: grid; margin: 0; font-size: 12.5px; line-height: 1.45; color: var(--mk-ink-muted, #a8a59a); }
.notes > span { grid-area: 1 / 1; visibility: hidden; }
.notes > span[data-shown] { visibility: visible; }
.reserve { min-height: calc(2 * 1.375em); }
.check { width: 16px; height: 16px; accent-color: var(--mk-signal, #ff5a2b); }
.range { width: 100%; min-height: 24px; accent-color: var(--mk-signal, #ff5a2b); }
.select {
  min-height: 38px;
  padding: 0 10px;
  border: 1px solid var(--mk-line-strong, #f3f0e8);
  border-radius: var(--mk-radius-s, 4px);
  background: var(--mk-bg, #0e0e0c);
  color: var(--mk-ink, #f3f0e8);
  font: inherit;
  font-size: 13.5px;
}
